  ('Weighted_Sit-Ups_-_With_Bands', 'other', 'strength', 'intermediate', 'abdominals', ARRAY[]::text[]),
  ('Wide_Stance_Barbell_Squat', 'barbell', 'strength', 'intermediate', 'quadriceps', ARRAY['calves','glutes','hamstrings','lower back']::text[]),
  ('Wide_Stance_Stiff_Legs', 'barbell', 'olympic weightlifting', 'intermediate', 'hamstrings', ARRAY['adductors','glutes','lower back']::text[]),
  ('Wide-Grip_Barbell_Bench_Press', 'barbell', 'strength', 'intermediate', 'chest', ARRAY['shoulders','triceps']::text[]),
  ('Wide-Grip_Decline_Barbell_Bench_Press', 'barbell', 'strength', 'intermediate', 'chest', ARRAY['shoulders','triceps']::text[]),
  ('Wide-Grip_Decline_Barbell_Pullover', 'barbell', 'strength', 'intermediate', 'chest', ARRAY['shoulders','triceps']::text[]),
  ('Wide-Grip_Lat_Pulldown', 'cable', 'strength', 'beginner', 'lats', ARRAY['biceps','middle back','shoulders']::text[]),
  ('Wide-Grip_Pulldown_Behind_The_Neck', 'cable', 'strength', 'intermediate', 'lats', ARRAY['biceps','middle back','shoulders']::text[]),
  ('Wide-Grip_Rear_Pull-Up', 'body only', 'strength', 'intermediate', 'lats', ARRAY['biceps','middle back','shoulders']::text[]),
  ('Wide-Grip_Standing_Barbell_Curl', 'barbell', 'strength', 'beginner', 'biceps', ARRAY[]::text[]),
  ('Windmills', NULL, 'stretching', 'intermediate', 'abductors', ARRAY['glutes','hamstrings','lower back']::text[]),
  ('Worlds_Greatest_Stretch', NULL, 'stretching', 'intermediate', 'hamstrings', ARRAY['calves','glutes','quadriceps']::text[]),
  ('Wrist_Roller', 'other', 'strength', 'beginner', 'forearms', ARRAY['shoulders']::text[]),
  ('Wrist_Rotations_with_Straight_Bar', 'barbell', 'strength', 'beginner', 'forearms', ARRAY[]::text[]),
  ('Yoke_Walk', 'other', 'strongman', 'intermediate', 'quadriceps', ARRAY['abdominals','abductors','adductors','calves','glutes','hamstrings','lower back']::text[]),
  ('Zercher_Squats', 'barbell', 'strength', 'expert', 'quadriceps', ARRAY['calves','glutes','hamstrings']::text[]),
  ('Zottman_Curl', 'dumbbell', 'strength', 'intermediate', 'biceps', ARRAY['forearms']::text[]),
  ('Zottman_Preacher_Curl', 'dumbbell', 'strength', 'intermediate', 'biceps', ARRAY['forearms']::text[])
) AS v(source_id, equipment, category, difficulty, target_muscle, secondary_muscles)
WHERE e.source = 'free-exercise-db' AND e.source_id = v.source_id;

-- Populate exercise_taxonomy from the now-enriched columns, so filter
-- dropdowns are data-driven instead of a hardcoded list in the mobile app.
INSERT INTO public.exercise_taxonomy (kind, value)
SELECT DISTINCT 'muscle', muscle_group FROM public.exercises WHERE muscle_group IS NOT NULL
UNION
SELECT DISTINCT 'body_part', body_part FROM public.exercises WHERE body_part IS NOT NULL
UNION
SELECT DISTINCT 'equipment', equipment FROM public.exercises WHERE equipment IS NOT NULL
UNION
SELECT DISTINCT 'category', category FROM public.exercises WHERE category IS NOT NULL
ON CONFLICT (kind, value) DO NOTHING;

-- ============================================================================
-- Favorites: new table, athlete-scoped, standard RLS pattern used everywhere
-- else in this schema (own-row-only via auth.uid()).
-- ============================================================================
CREATE TABLE IF NOT EXISTS public.exercise_favorites (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id UUID NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
  exercise_id UUID NOT NULL REFERENCES public.exercises(id) ON DELETE CASCADE,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  UNIQUE (user_id, exercise_id)
);

ALTER TABLE public.exercise_favorites ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Users manage their own favorites" ON public.exercise_favorites;
CREATE POLICY "Users manage their own favorites"
  ON public.exercise_favorites FOR ALL
  USING (auth.uid() = user_id)
  WITH CHECK (auth.uid() = user_id);

CREATE INDEX IF NOT EXISTS idx_exercise_favorites_user ON public.exercise_favorites(user_id);
